const KURRO_API=(window.location.hostname==='script.google.com'||window.location.hostname.endsWith('.googleusercontent.com'))?window.location.origin+window.location.pathname:'https://script.google.com/macros/s/AKfycbz9CHAxNnfG0PBYIO1CHcUlbOLXh6noYYYOc6P6coo7576GKreW0qMdkZJecbdT1SwMOw/exec';
