function kurroRequest(params){return new Promise((resolve,reject)=>{const callback='kurro_'+Date.now()+'_'+Math.random().toString(36).slice(2),script=document.createElement('script');let settled=false,expired=false;const finish=(fn,value)=>{if(settled&&!expired)return;settled=true;expired=false;clearTimeout(timer);delete window[callback];script.remove();fn(value)};const timer=setTimeout(()=>{settled=true;expired=true;reject(new Error('Tiempo de espera agotado'));setTimeout(()=>{delete window[callback];script.remove()},60000)},30000);window[callback]=data=>{if(expired)return;if(data?.ok)finish(resolve,data.result);else finish(reject,new Error('Respuesta no válida'))};script.onerror=()=>{if(!expired)finish(reject,new Error('No se pudo conectar'))};script.src=KURRO_API+'?'+new URLSearchParams({...params,callback,_:Date.now()}).toString();document.body.appendChild(script)})}
function gvizRequest(sheet){return new Promise((resolve,reject)=>{const cb='gviz_'+Date.now()+'_'+Math.random().toString(36).slice(2),script=document.createElement('script');let settled=false;const finish=(fn,value)=>{if(settled)return;settled=true;clearTimeout(timer);delete window[cb];script.remove();fn(value)};const timer=setTimeout(()=>finish(reject,new Error('Lectura directa agotada')),12000);const receive=payload=>{const table=payload?.table||payload;if(!table?.cols||!table?.rows)return finish(reject,new Error('Formato de hoja no válido'));const values=[table.cols.map(c=>c.label||'')];table.rows.forEach(row=>values.push((row.c||[]).map(cell=>cell?.f??cell?.v??'')));finish(resolve,values)};window[cb]=receive;window.google=window.google||{};window.google.visualization=window.google.visualization||{};window.google.visualization.Query=window.google.visualization.Query||{};window.google.visualization.Query.setResponse=receive;script.onerror=()=>finish(reject,new Error('No se pudo leer Google Sheets'));script.src=KURRO_SHEET+'?'+new URLSearchParams({sheet,tqx:'out:json;responseHandler:'+cb,_:Date.now()});document.body.appendChild(script)})}
async function loadGvizData(){const [planning,pending,clients]=await Promise.all([gvizRequest('Registro Maestro'),gvizRequest('Seguimientos'),gvizRequest('Clientes')]);const header=pending[0]||[],personCol=header.indexOf('Persona o empresa');const forPerson=person=>[pending[0],...pending.slice(1).filter(row=>String(row[personCol]||'').trim()===person)];return{planning:{id:KURRO_SOURCE_ID,name:'Registro Maestro',values:planning},miguel:{id:KURRO_SOURCE_ID,name:'Seguimientos',values:forPerson('Miguel')},properval:{id:KURRO_SOURCE_ID,name:'Seguimientos',values:forPerson('Properval')},clients:{id:KURRO_SOURCE_ID,name:'Clientes',values:clients}}}
